import { getTranslations, translate, Language, languages } from '@/lib/translations';

export function generateStaticParams() {
  return languages.map((lang) => ({ lang }));
}

interface ContactProps {
  params: Promise<{ lang: Language }>;
}

export default async function Contact({ params }: ContactProps) {
  const { lang } = await params;
  const translations = getTranslations(lang);
  const t = (key: string, params?: Record<string, string>) => 
    translate(translations, key, params);

  const isRTL = lang === 'ar';

  return (
    <main className="container mx-auto px-4 py-12">
      <div className="max-w-2xl mx-auto">
        <h1 className="text-4xl font-bold text-gray-900 mb-8">{t('contact.title')}</h1>
        <p className="text-lg text-gray-700 mb-8">
          {t('contact.description')}
        </p>
        <form className="space-y-6" dir={isRTL ? 'rtl' : 'ltr'}>
          <div>
            <label htmlFor="fullName" className="block text-sm font-medium text-gray-700 mb-2">
              {t('contact.form.fullName')}
            </label>
            <input
              type="text"
              id="fullName"
              name="fullName"
              required
              className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-green-700 focus:border-green-700"
            />
          </div>
          <div>
            <label htmlFor="company" className="block text-sm font-medium text-gray-700 mb-2">
              {t('contact.form.company')}
            </label>
            <input
              type="text"
              id="company"
              name="company"
              className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-green-700 focus:border-green-700"
            />
          </div>
          <div>
            <label htmlFor="country" className="block text-sm font-medium text-gray-700 mb-2">
              {t('contact.form.country')}
            </label>
            <input
              type="text"
              id="country"
              name="country"
              required
              className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-green-700 focus:border-green-700"
            />
          </div>
          <div>
            <label htmlFor="email" className="block text-sm font-medium text-gray-700 mb-2">
              {t('contact.form.email')}
            </label>
            <input
              type="email"
              id="email"
              name="email"
              required
              className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-green-700 focus:border-green-700"
            />
          </div>
          <div>
            <label htmlFor="productInterest" className="block text-sm font-medium text-gray-700 mb-2">
              {t('contact.form.productInterest')}
            </label>
            <input
              type="text"
              id="productInterest"
              name="productInterest"
              className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-green-700 focus:border-green-700"
            />
          </div>
          <div>
            <label htmlFor="message" className="block text-sm font-medium text-gray-700 mb-2">
              {t('contact.form.message')}
            </label>
            <textarea
              id="message"
              name="message"
              rows={6}
              required
              className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-green-700 focus:border-green-700"
            ></textarea>
          </div>
          <button
            type="submit"
            className="w-full bg-green-700 text-white px-6 py-3 rounded-lg hover:bg-green-800 transition-colors font-medium"
          >
            {t('contact.form.submit')}
          </button>
        </form>
        {/* Form provider will be integrated later */}
      </div>
    </main>
  );
}

